head.script:
scwin.init = function() {
    radio1.setValue("1");
    for (var i = 0; i < 30; i++) {
        scwin.itemsetData.push("label=" + i);
        scwin.itemsetData.push(i + "");
    }
    dataList2.setData(scwin.itemsetData.slice(0));
    dataList3.setData(scwin.itemsetData.slice(0));
    dataList4.setData(scwin.itemsetData.slice(0));
    dataList1.setData(scwin.data1.slice(0));
}
scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    // return false;
    return true;
}
scwin.trigger1_onclick = function() {
    var row = dataList1.getTotalRow();
    for (var i = 0; i < row; i++) {
        console.log(i + " ::::: " + dataList1.getCellData(i, 'col3'));
    }
};
