scwin.formatter = function(data) {
    console.log(data);
};
scwin.search = function() {
    if (radio1.getValue() == "2") {
        dataList1.setData(scwin.data2.slice(0));
    } else {
        dataList1.setData(scwin.data1.slice(0));
    }
};
scwin.trigger3_onclick = function(e) {
    scwin.search();
};
scwin.grid1_groupbyFilterBoxFormatter = function(data, isGroupby) {
    //console.log(data);
    var label = "";
    var labelArr = [];
    var groupbyStr = isGroupby ? "(groupby)" : "";
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        if (filter.length === 0) {
            s_label = "-null-";
        } else {
            for (var j = 0; j < filter.length; j++) {
                if (filter[j].gate) {
                    s_label = s_label + " " + filter[j].gate + " ";
                }
                // var values = filter[j].values;
                var labels = filter[j].labels; // filter[j].values를 할 경우 value를, labels를 참조할 경우 label을 가져온다.
                if (labels.join) {
                    labels = "[" + labels.join(" ,") + "]";
                }
                s_label = s_label + filter[j].operator + " " + labels;
            }
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = groupbyStr + labelArr.join(" & ");
    return label;
};
